import {Buffer} from 'node:buffer';
import png from 'pngjs/browser.js';
const {PNG}=png;

// Only accept the PNG format generated by our photo picker. Decode and rewrite
// the pixels so uploaded metadata and extra chunks are never stored.
export function cleanPhoto(bytes:Uint8Array):Uint8Array {
 const input=Buffer.from(bytes);
 if(input.length<33||!input.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10]))||input.toString('ascii',12,16)!=='IHDR'||input.readUInt32BE(8)!==13)throw new Error('Foto inválida. Escolha outra imagem.');
 const width=input.readUInt32BE(16),height=input.readUInt32BE(20);
 if(!width||!height||width>1280||height>1280||input[24]!==8||input[28]!==0)throw new Error('Foto muito grande. Escolha a imagem novamente.');
 const decoded=PNG.sync.read(input,{checkCRC:true});
 const output=PNG.sync.write(decoded,{colorType:6,bitDepth:8});
 if(output.length>3145728)throw new Error('Foto muito grande. Escolha uma imagem menor.');
 return new Uint8Array(output);
}
